<?php
/** Shared Google OAuth/resource boundary. No consumer may persist Google tokens. */
if (!defined('ABSPATH')) { exit; }
final class Estandar_Google_Integration_Hub {
    const OPTION='estandar_google_integration_hub'; const TOKEN='estandar_google_hub_access_token';
    public static function settings(): array { $d=array('client_id'=>'','client_secret'=>'','refresh_token'=>'','scopes'=>array('https://www.googleapis.com/auth/webmasters.readonly','https://www.googleapis.com/auth/datamanager'),'developer_token'=>'','resources'=>array(),'inventory'=>array(),'revoked'=>false,'last_error'=>'','last_refresh'=>''); $v=get_option(self::OPTION,array()); return array_merge($d,is_array($v)?$v:array()); }
    public static function save(array $v): void { $old=self::settings(); $next=array_merge($old,array_intersect_key($v,$old)); foreach(array('client_secret','refresh_token','developer_token') as $k){if(empty($v[$k])){$next[$k]=$old[$k];}} $next['scopes']=array_values(array_unique(array_filter(array_map('strval',(array)$next['scopes'])))); $next['revoked']=false; update_option(self::OPTION,$next,false); delete_transient(self::TOKEN); }
    public static function get_access_token(string $service=''): array { $s=self::settings(); if($s['revoked']||$s['client_id']===''||$s['client_secret']===''||$s['refresh_token']===''){return array('token'=>'','status'=>'not_configured','message'=>'Google OAuth is not configured.');} $cached=get_transient(self::TOKEN); if(is_string($cached)&&$cached!==''){return array('token'=>$cached,'status'=>'available','message'=>'');} $r=wp_remote_post('https://oauth2.googleapis.com/token',array('timeout'=>20,'body'=>array('grant_type'=>'refresh_token','client_id'=>$s['client_id'],'client_secret'=>$s['client_secret'],'refresh_token'=>$s['refresh_token']))); if(is_wp_error($r)){return self::error('token_endpoint_unreachable');} $data=json_decode((string)wp_remote_retrieve_body($r),true); $token=is_array($data)?trim((string)($data['access_token']??'')):''; if((int)wp_remote_retrieve_response_code($r)!==200||$token===''){return self::error('token_refresh_failed');} set_transient(self::TOKEN,$token,max(60,(int)($data['expires_in']??3600)-60)); $s['last_refresh']=gmdate('Y-m-d H:i:s');$s['last_error']='';update_option(self::OPTION,$s,false);return array('token'=>$token,'status'=>'available','message'=>''); }
    public static function revoke(): void {$s=self::settings();$s['revoked']=true;$s['refresh_token']='';$s['last_error']='revoked';update_option(self::OPTION,$s,false);delete_transient(self::TOKEN);}
    public static function selected(string $service){$r=self::settings()['resources'];return $r[$service]??array();}
    public static function select(string $service,array $resources):bool{$s=self::settings();$valid=array_column((array)($s['inventory'][$service]['resources']??array()),'id');foreach($resources as $id){if(!in_array((string)$id,$valid,true))return false;}$s['resources'][$service]=array_values(array_map('strval',$resources));update_option(self::OPTION,$s,false);return true;}
    public static function status(): array {$s=self::settings();$token=self::get_access_token();$services=array('search_console','google_ads','ga4','gtm');$out=array();foreach($services as $v){$out[$v]=array('connected'=>$token['status']==='available','selected'=>self::selected($v),'developer_token_required'=>$v==='google_ads','developer_token_present'=>$s['developer_token']!=='');}return array('oauth'=>$token['status'],'services'=>$out,'last_refresh'=>$s['last_refresh'],'last_error'=>$s['last_error']);}
    public static function discover(string $service): array { $t=self::get_access_token($service);$base=array('service'=>$service,'resources'=>array(),'error'=>'','discovered_at'=>gmdate('c'));if($t['token']==='')return array_merge($base,array('status'=>$t['status']));$s=self::settings();if($service==='google_ads'&&$s['developer_token']==='')return array_merge($base,array('status'=>'developer_token_required'));$r=apply_filters('estandar_google_hub_discover_'.$service,null,$t['token'],$s['developer_token']);if(!is_array($r)){$r=self::remote_discover($service,$t['token'],$s['developer_token']);}$r=array_merge($base,$r);if(($r['status']??'error')==='available'){ $s['inventory'][$service]=array('resources'=>array_values((array)$r['resources']),'discovered_at'=>$r['discovered_at']);update_option(self::OPTION,$s,false);}elseif(!empty($s['inventory'][$service])){$r['resources']=$s['inventory'][$service]['resources'];}return $r; }
    private static function remote_discover(string $service,string $token,string $developer):array{$urls=array('search_console'=>'https://searchconsole.googleapis.com/webmasters/v3/sites','google_ads'=>'https://googleads.googleapis.com/v18/customers:listAccessibleCustomers','ga4'=>'https://analyticsadmin.googleapis.com/v1beta/accounts','gtm'=>'https://tagmanager.googleapis.com/tagmanager/v2/accounts');if(empty($urls[$service]))return array('status'=>'unsupported','resources'=>array(),'error'=>'');$headers=array('Authorization'=>'Bearer '.$token);if($service==='google_ads')$headers['developer-token']=$developer;$r=wp_remote_get($urls[$service],array('timeout'=>20,'headers'=>$headers));if(is_wp_error($r))return array('status'=>'temporary_error','resources'=>array(),'error'=>'remote_unavailable');$code=(int)wp_remote_retrieve_response_code($r);if($code!==200)return array('status'=>$code===401||$code===403?'not_authorized':'temporary_error','resources'=>array(),'error'=>'http_'.$code);$d=json_decode((string)wp_remote_retrieve_body($r),true);$items=$service==='search_console'?($d['siteEntry']??array()):($d['resourceNames']??($d['accounts']??array()));$out=array();foreach((array)$items as $x){if(is_array($x)){$id=(string)($x['siteUrl']??$x['name']??'');$label=(string)($x['displayName']??$id);}else{$id=(string)$x;$label=$id;}if($id!=='')$out[]=array('id'=>$id,'label'=>$label);}return array('status'=>'available','resources'=>$out,'error'=>'');}
    private static function error(string $code):array{$s=self::settings();$s['last_error']=$code;update_option(self::OPTION,$s,false);return array('token'=>'','status'=>'error','message'=>$code);}
    public static function init(): void { add_action('admin_post_estandar_google_hub_connect',array(__CLASS__,'connect')); add_action('admin_post_estandar_google_hub_callback',array(__CLASS__,'callback')); add_action('admin_post_estandar_google_hub_revoke',array(__CLASS__,'revoke_request')); add_action('admin_post_estandar_google_hub_discover',array(__CLASS__,'discover_request')); }
    public static function redirect_uri(): string { return admin_url('admin-post.php?action=estandar_google_hub_callback'); }
    public static function connect(): void { self::guard('estandar_google_hub_connect'); $s=self::settings(); if($s['client_id']===''){wp_die('Google OAuth Client no configurado.');} $state=wp_generate_password(48,false,false); $verifier=wp_generate_password(64,false,false); set_transient('estandar_google_hub_state_'.$state,array('user'=>get_current_user_id(),'verifier'=>$verifier),600); $challenge=rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='); $scopes=implode(' ',array_filter((array)$s['scopes'])); $url='https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(array('client_id'=>$s['client_id'],'redirect_uri'=>self::redirect_uri(),'response_type'=>'code','access_type'=>'offline','prompt'=>'consent','scope'=>$scopes,'state'=>$state,'code_challenge'=>$challenge,'code_challenge_method'=>'S256'),'','&',PHP_QUERY_RFC3986); wp_safe_redirect($url); exit; }
    public static function callback(): void { if(!current_user_can('manage_options')){wp_die('Sin permisos.');} $state=sanitize_text_field((string)($_GET['state']??''));$key='estandar_google_hub_state_'.$state;$pending=get_transient($key);delete_transient($key);if(!is_array($pending)||(int)$pending['user']!==get_current_user_id()){wp_die('OAuth state inválido o expirado.');} if(!empty($_GET['error'])){self::error('oauth_cancelled');wp_safe_redirect(admin_url('admin.php?page=estandar_projects_integrations&provider=google'));exit;} $code=sanitize_text_field((string)($_GET['code']??''));if($code===''){wp_die('OAuth callback sin código.');}$s=self::settings();$r=wp_remote_post('https://oauth2.googleapis.com/token',array('timeout'=>20,'body'=>array('code'=>$code,'client_id'=>$s['client_id'],'client_secret'=>$s['client_secret'],'redirect_uri'=>self::redirect_uri(),'grant_type'=>'authorization_code','code_verifier'=>$pending['verifier'])));$data=is_wp_error($r)?array():json_decode((string)wp_remote_retrieve_body($r),true);if((int)wp_remote_retrieve_response_code($r)!==200||empty($data['refresh_token'])){self::error('oauth_exchange_failed');wp_die('No fue posible completar OAuth.');}$s['refresh_token']=(string)$data['refresh_token'];$s['revoked']=false;$s['last_error']='';update_option(self::OPTION,$s,false);delete_transient(self::TOKEN);wp_safe_redirect(admin_url('admin.php?page=estandar_projects_integrations&provider=google'));exit; }
    public static function revoke_request():void {self::guard('estandar_google_hub_revoke');self::revoke();wp_safe_redirect(admin_url('admin.php?page=estandar_projects_integrations&provider=google'));exit;}
    public static function discover_request():void {self::guard('estandar_google_hub_discover');foreach(array('search_console','google_ads','ga4','gtm') as $service){self::discover($service);}wp_safe_redirect(admin_url('admin.php?page=estandar_projects_integrations&provider=google'));exit;}
    private static function guard(string $nonce):void {if(!current_user_can('manage_options')){wp_die('Sin permisos.');}check_admin_referer($nonce);}
}
if (class_exists('Estandar_Integration_Provider')) { final class Estandar_Google_Hub_Provider extends Estandar_Integration_Provider {
 public function id():string{return 'google';} public function label():string{return 'Google';} public function description():string{return 'Conexión única Google para Search Console, Ads discovery, GA4 y Tag Manager.';}
 public function get_settings():array{return Estandar_Google_Integration_Hub::settings();} public function save_settings(array $p):void{Estandar_Google_Integration_Hub::save(array('client_id'=>sanitize_text_field($p['google_hub_client_id']??''),'client_secret'=>sanitize_text_field($p['google_hub_client_secret']??''),'developer_token'=>sanitize_text_field($p['google_hub_developer_token']??'')));if(isset($p['google_hub_search_console']))Estandar_Google_Integration_Hub::select('search_console',array(sanitize_text_field($p['google_hub_search_console'])));}
 public function settings_fields():array{$s=$this->get_settings();$opts=array(''=>'Descubrir recursos primero');foreach((array)($s['inventory']['search_console']['resources']??array())as$r){$opts[$r['id']]=$r['label'];}return array(array('name'=>'google_hub_client_id','label'=>'OAuth Client ID','type'=>'text','value'=>$s['client_id']),array('name'=>'google_hub_client_secret','label'=>'OAuth Client Secret','type'=>'password','value'=>'','placeholder'=>$s['client_secret']!==''?'•••••••• (guardado)':''),array('name'=>'google_hub_search_console','label'=>'Propiedad Search Console','type'=>'select','value'=>(string)(Estandar_Google_Integration_Hub::selected('search_console')[0]??''),'options'=>$opts));}
 public function status():array{$x=Estandar_Google_Integration_Hub::status();return array('configured'=>$x['oauth']!=='not_configured','active'=>$x['oauth']==='available','summary'=>'OAuth: '.$x['oauth']);}
 public function render_extra():void{$s=Estandar_Google_Integration_Hub::settings();echo '<p><strong>Redirect URI:</strong> <code>'.esc_html(Estandar_Google_Integration_Hub::redirect_uri()).'</code></p>';foreach(array('connect'=>'Conectar con Google','revoke'=>'Revocar conexión','discover'=>'Actualizar recursos')as $a=>$label){echo '<form style="display:inline" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="estandar_google_hub_'.$a.'">';wp_nonce_field('estandar_google_hub_'.$a);submit_button($label,'secondary','submit',false);echo '</form> ';}foreach(array('search_console','google_ads','ga4','gtm')as $service){$i=$s['inventory'][$service]??array();echo '<p><strong>'.esc_html($service).':</strong> '.esc_html(!empty($i['discovered_at'])?'inventario disponible':'sin inventario').'</p>';}}
} add_action('estandar_integrations_register',static function(){Estandar_Integration_Registry::register(new Estandar_Google_Hub_Provider());}); }
